import os; os.makedirs("tests/shots", exist_ok=True)
from playwright.sync_api import sync_playwright
B="http://localhost:8123"; res=[]
def ck(n,ok,d=""): res.append(ok); print(("PASS " if ok else "FAIL ")+n+(f" [{d}]" if d else ""))
blk=lambda r:r.abort()
def mouse_pos(pg): return pg.evaluate("(()=>{const m=new DOMMatrix(getComputedStyle(document.querySelector('.gc')).transform);return [m.e,m.f]})()")
with sync_playwright() as p:
    b=p.chromium.launch()
    # ================= CURSOR (isolated: styleguide.html) =================
    ctx=b.new_context(viewport={"width":1280,"height":800}); ctx.route("**/fonts.g*/**",blk)
    pg=ctx.new_page(); errs=[]; pg.on("pageerror",lambda e:errs.append(str(e))); pg.goto(B+"/styleguide.html"); pg.wait_for_timeout(500)
    ck("cursor: orb element + label slot created",pg.locator(".gc .gc__orb .gc__label").count()==1 and not errs,str(errs))
    ck("cursor: native pointer NOT hidden on plain page",pg.evaluate("getComputedStyle(document.body).cursor")!="none")
    ck("cursor: hidden before first move",not pg.evaluate("document.querySelector('.gc').classList.contains('is-visible')"))
    pg.mouse.move(200,200); pg.mouse.move(900,500); xs=[]
    for i in range(6): xs.append(mouse_pos(pg)[0]); pg.wait_for_timeout(40)
    pg.wait_for_timeout(900); fin=mouse_pos(pg)
    ck("cursor: trailing lag then settles on pointer",xs[0]<890 and xs==sorted(xs) and abs(fin[0]-900)<1.5 and abs(fin[1]-500)<1.5,f"x samples {[round(x) for x in xs]} final {[round(v) for v in fin]}")
    sz=lambda: pg.evaluate("document.querySelector('.gc__orb').getBoundingClientRect().width")
    pg.screenshot(path="tests/shots/cur_default.png",clip={"x":800,"y":420,"width":200,"height":160})
    ck("cursor: default orb ~46px",abs(sz()-46)<3,f"{sz():.0f}px")
    # plain hover
    pg.locator("#cursor-light").scroll_into_view_if_needed(); pg.wait_for_timeout(300)
    bx=pg.locator("#cursor-light .btn").first.bounding_box(); pg.mouse.move(bx["x"]+bx["width"]/2,bx["y"]+bx["height"]/2); pg.wait_for_timeout(800)
    ck("cursor: hover state expands orb (~66px), native pointer kept",pg.get_attribute(".gc","data-state")=="hover" and abs(sz()-66)<3 and pg.evaluate("getComputedStyle(document.querySelector('#cursor-light .btn')).cursor")!="none",f"{sz():.0f}px")
    # labels
    for sel,txt in [('[data-cursor-label="OPEN BOOK"]',"OPEN BOOK"),('[data-cursor-label="VIEW PROJECT"]',"VIEW PROJECT")]:
        bx=pg.locator("#cursor-light "+sel).bounding_box(); pg.mouse.move(bx["x"]+bx["width"]/2,bx["y"]+bx["height"]/2); pg.wait_for_timeout(900)
        ck(f"cursor: label '{txt}' shown in a larger orb",pg.get_attribute(".gc","data-state")=="label" and pg.inner_text(".gc__label")==txt and abs(sz()-104)<4 and pg.evaluate("getComputedStyle(document.querySelector('.gc__label')).opacity")=="1",f"{sz():.0f}px")
        ck(f"cursor: native pointer hidden only on the labelled target ({txt})",pg.evaluate(f"getComputedStyle(document.querySelector('#cursor-light {sel}')).cursor")=="none")
        if txt=="OPEN BOOK": pg.screenshot(path="tests/shots/cur_label_light.png",clip={"x":max(bx['x']+bx['width']/2-120,0),"y":bx['y']-60,"width":240,"height":180})
    # click not blocked
    pg.mouse.click(bx["x"]+bx["width"]/2,bx["y"]+bx["height"]/2); pg.wait_for_timeout(200)
    ck("cursor: clicking through the orb works (hash changed)",pg.evaluate("location.hash")=="#cursor-light")
    ck("cursor: orb has pointer-events:none",pg.evaluate("getComputedStyle(document.querySelector('.gc')).pointerEvents")=="none")
    # text selection
    pg.wait_for_timeout(900); t=pg.locator("#sg-text").bounding_box(); ly=t["y"]+10; pg.mouse.move(t["x"]+2,ly); pg.mouse.down(); pg.mouse.move(t["x"]+t["width"]-5,ly,steps=10); pg.mouse.up()
    sel=pg.evaluate("getSelection().toString().length")
    ck("cursor: text selection still works",sel>20,f"{sel} chars selected")
    ck("cursor: native I-beam/auto cursor on text (not hidden)",pg.evaluate("getComputedStyle(document.querySelector('#sg-text')).cursor")!="none")
    inp=pg.locator("#sg-light").bounding_box(); pg.mouse.move(inp["x"]+30,inp["y"]+10); pg.wait_for_timeout(500)
    ck("cursor: orb hides over text input",pg.get_attribute(".gc","data-state")=="text" and pg.evaluate("getComputedStyle(document.querySelector('.gc')).opacity")=="0")
    # dark tone
    pg.locator("#cursor-dark").scroll_into_view_if_needed(); pg.wait_for_timeout(300)
    bx=pg.locator('#cursor-dark [data-cursor-label]').bounding_box(); pg.mouse.move(bx["x"]+bx["width"]/2,bx["y"]+bx["height"]/2); pg.wait_for_timeout(900)
    ck("cursor: dark tone + label on forest section",pg.get_attribute(".gc","data-tone")=="dark" and pg.get_attribute(".gc","data-state")=="label")
    pg.screenshot(path="tests/shots/cur_label_dark.png",clip={"x":max(bx['x']+bx['width']/2-120,0),"y":bx['y']-60,"width":240,"height":180})
    # perf: loop idles
    a=pg.evaluate("document.querySelector('.gc').style.transform"); pg.wait_for_timeout(300); ck("cursor: animation loop idles when still",a==pg.evaluate("document.querySelector('.gc').style.transform"))
    ctx.close()
    # touch + reduced motion
    tc=b.new_context(viewport={"width":390,"height":844},is_mobile=True,has_touch=True); tp=tc.new_page(); tp.goto(B+"/styleguide.html"); tp.wait_for_timeout(400)
    ck("cursor: disabled on touch devices",tp.locator(".gc").count()==0); tc.close()
    rc=b.new_context(viewport={"width":1280,"height":800},reduced_motion="reduce"); rp=rc.new_page(); rp.goto(B+"/styleguide.html"); rp.mouse.move(300,300); rp.wait_for_timeout(300)
    ck("cursor: disabled with prefers-reduced-motion",rp.locator(".gc").count()==0); rc.close()

    # ================= TYPING (isolated: demos/book-typing.html) =================
    ctx=b.new_context(viewport={"width":1440,"height":900}); ctx.route("**/fonts.g*/**",blk)
    pg=ctx.new_page(); errs=[]; pg.on("pageerror",lambda e:errs.append(str(e))); pg.goto(B+"/demos/book-typing.html"); pg.wait_for_timeout(900)
    idx=lambda: pg.evaluate("Portfolio.book.index"); played=lambda: pg.evaluate("Portfolio.book.played()")
    ck("typing: demo loads with no errors, book closed",idx()==0 and not errs,str(errs))
    ck("typing: nothing played while closed",played()=={"left":[],"right":[]})
    pg.evaluate("Portfolio.book.open()"); pg.wait_for_timeout(450)
    st=pg.evaluate("Portfolio.book.pf.getState()")
    ck("typing: 3D page turn is running (state=flipping)",st=="flipping",st)
    # genuine turn evidence: flip animation draws pages with changing geometry/shadow
    a=pg.evaluate("(()=>{const c=document.querySelector('.stf__item[style*=\"transform\"]')||document.querySelector('.stf__block');return [...document.querySelectorAll('.stf__item')].map(e=>e.style.cssText.length+'|'+(e.style.transform||'')+'|'+(e.style.clipPath||'')).join(';')})()")
    pg.wait_for_timeout(120)
    bq=pg.evaluate("[...document.querySelectorAll('.stf__item')].map(e=>e.style.cssText.length+'|'+(e.style.transform||'')+'|'+(e.style.clipPath||'')).join(';')")
    ck("typing: page element geometry changes mid-flip (real flip, not a fade)",a!=bq)
    pendingMid=pg.evaluate("document.querySelector('.page--right[data-project=\"1\"]').classList.contains('is-pending')")
    pg.screenshot(path="tests/shots/typ_midflip.png")
    ck("typing: content stays hidden during the turn (typing is a layer AFTER it)",pendingMid)
    pg.wait_for_timeout(1000)
    ck("typing: flip finished -> spread 1 shown",idx()==1,f"idx={idx()}")
    pg.wait_for_timeout(250)
    car=pg.locator(".ty-caret").count(); done=pg.evaluate("(document.querySelector('.page--right[data-project=\"1\"] .ty-done')||{}).textContent")
    ck("typing: typing starts after the turn with a caret",car==1 and len(done or '')>0 and not pg.evaluate("document.querySelector('.page--right[data-project=\"1\"]').classList.contains('is-pending')"),f"typed so far: {done!r}")
    ck("typing: caret blinks (animation applied)",pg.evaluate("getComputedStyle(document.querySelector('.ty-caret')).animationName")=="ty-blink")
    pg.screenshot(path="tests/shots/typ_typing.png")
    ck("typing: layout reserved (no jump): hidden remainder holds space",pg.evaluate("(()=>{const t=document.querySelector('.page--right[data-project=\"1\"] .page__title');return t.getBoundingClientRect().height>10})()"))
    left=pg.evaluate("document.querySelector('.page--left[data-project=\"1\"]').classList.contains('is-pending')")
    ck("typing: screenshots reveal (wipe transition set up, pending cleared)",not left and pg.evaluate("getComputedStyle(document.querySelector('.page--left[data-project=\"1\"] .page__shot img')).transitionProperty").startswith("clip-path"))
    pg.wait_for_timeout(7000)
    full=pg.evaluate("(()=>{const r=document.querySelector('.page--right[data-project=\"1\"]');return [r.querySelector('.page__title').textContent.trim(), r.querySelectorAll('.ty').length, r.querySelectorAll('.ty-caret').length]})()")
    ck("typing: finishes, clean text restored, caret removed",full[0]=="[Add project 1 title]" and full[1]==0 and full[2]==0,str(full))
    ck("typing: link visible after sequence",pg.evaluate("getComputedStyle(document.querySelector('.page--right[data-project=\"1\"] .page__link')).opacity")=="1")
    pg.screenshot(path="tests/shots/typ_done.png")
    # next project plays, back does NOT replay
    pg.click("[data-book-next]"); pg.wait_for_timeout(1500)
    ck("typing: project 2 content typed on arrival",idx()==3 and played()["right"]==["1","2"] and pg.locator(".page--right[data-project='2'] .ty-caret").count()>=0,str(played()))
    pg.wait_for_timeout(7000)
    pg.click("[data-book-prev]"); pg.wait_for_timeout(1400)
    c=pg.locator(".page--right[data-project='1'] .ty-caret").count(); pend=pg.evaluate("document.querySelector('.page--right[data-project=\"1\"]').classList.contains('is-pending')")
    ck("typing: going back does NOT replay project 1 (text instantly visible)",idx()==1 and c==0 and not pend and pg.evaluate("getComputedStyle(document.querySelector('.page--right[data-project=\"1\"] .page__title')).visibility")=="visible",f"carets={c}")
    pg.click("[data-book-next]"); pg.wait_for_timeout(1400)
    ck("typing: forward again does NOT replay project 2",pg.locator(".page--right[data-project='2'] .ty-caret").count()==0 and played()["right"]==["1","2"],str(played()))
    pg.click("[data-book-next]"); pg.wait_for_timeout(1500); pg.wait_for_timeout(7000)
    ck("typing: project 3 played once; all played set",played()["right"]==["1","2","3"],str(played()))
    ck("typing: real page-turns still work after typing (back cover reached)",idx()==5 or idx()==7,f"idx={idx()}")
    ctx.close()
    # reduced motion: no typing, no pending
    rc=b.new_context(viewport={"width":1440,"height":900},reduced_motion="reduce"); rc.route("**/fonts.g*/**",blk); rp=rc.new_page(); rp.goto(B+"/demos/book-typing.html"); rp.wait_for_timeout(800)
    ck("typing: reduced-motion -> no pending/typing markup at all",rp.locator(".is-pending").count()==0 and rp.locator(".ty").count()==0)
    rp.evaluate("Portfolio.book.open()"); rp.wait_for_timeout(1200)
    ck("typing: reduced-motion -> content visible immediately, page still turns",rp.evaluate("Portfolio.book.index")==1 and rp.locator(".ty-caret").count()==0 and rp.evaluate("getComputedStyle(document.querySelector('.page--right[data-project=\"1\"] .page__title')).visibility")=="visible")
    rc.close()
    # mobile portrait
    mc=b.new_context(viewport={"width":390,"height":844},is_mobile=True,has_touch=True,device_scale_factor=2); mc.route("**/fonts.g*/**",blk); mp=mc.new_page(); mp.goto(B+"/demos/book-typing.html"); mp.wait_for_timeout(900)
    mp.tap("[data-book-toggle]"); mp.wait_for_timeout(2000)
    ck("typing mobile: left page (screenshots) revealed on arrival",mp.evaluate("Portfolio.book.index")==1 and not mp.evaluate("document.querySelector('.page--left[data-project=\"1\"]').classList.contains('is-pending')") and mp.evaluate("Portfolio.book.played()")["left"]==["1"])
    mp.tap("[data-book-next]"); mp.wait_for_timeout(1400)
    ck("typing mobile: right page types on page 2",mp.evaluate("Portfolio.book.index")==2 and mp.evaluate("Portfolio.book.played()")["right"]==["1"])
    mp.wait_for_timeout(7000); mp.screenshot(path="tests/shots/typ_mobile.png")
    ov=mp.evaluate("(()=>{const i=document.querySelector('.page--right[data-project=\"1\"] .page__inner');return [i.scrollHeight,i.clientHeight]})()")
    ck("mobile book: right-page content fits (no overflow)",ov[0]<=ov[1]+1,str(ov))
    mc.close(); b.close()
print(f"\nTOTAL {len(res)} PASS {sum(res)} FAIL {len(res)-sum(res)}")
